// Differential checks of ArrayAppend-faithful.js against Lean, generated by leanscript --check
import * as M from "./ArrayAppend-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test2([], [])", () => M.test2([], []), "#[]", false);
check("test2([], [0n])", () => M.test2([], [0n]), "#[0]", false);
check("test2([0n], [])", () => M.test2([0n], []), "#[0]", false);
check("test2([], [0n, 1n, 2n])", () => M.test2([], [0n, 1n, 2n]), "#[0, 1, 2]", false);
check("test2([0n], [0n])", () => M.test2([0n], [0n]), "#[0, 0]", false);
check("test2([0n, 1n, 2n], [])", () => M.test2([0n, 1n, 2n], []), "#[0, 1, 2]", false);
check("test2([], [13n, 5n, 2n, 1n])", () => M.test2([], [13n, 5n, 2n, 1n]), "#[13, 5, 2, 1]", false);
check("test2([0n], [0n, 1n, 2n])", () => M.test2([0n], [0n, 1n, 2n]), "#[0, 0, 1, 2]", false);
check("test2([0n, 1n, 2n], [0n])", () => M.test2([0n, 1n, 2n], [0n]), "#[0, 1, 2, 0]", false);
check("test2([13n, 5n, 2n, 1n], [])", () => M.test2([13n, 5n, 2n, 1n], []), "#[13, 5, 2, 1]", false);
check("test2([0n], [13n, 5n, 2n, 1n])", () => M.test2([0n], [13n, 5n, 2n, 1n]), "#[0, 13, 5, 2, 1]", false);
check("test2([0n, 1n, 2n], [0n, 1n, 2n])", () => M.test2([0n, 1n, 2n], [0n, 1n, 2n]), "#[0, 1, 2, 0, 1, 2]", false);
check("test2([13n, 5n, 2n, 1n], [0n])", () => M.test2([13n, 5n, 2n, 1n], [0n]), "#[13, 5, 2, 1, 0]", false);
check("test2([0n, 1n, 2n], [13n, 5n, 2n, 1n])", () => M.test2([0n, 1n, 2n], [13n, 5n, 2n, 1n]), "#[0, 1, 2, 13, 5, 2, 1]", false);
check("test2([13n, 5n, 2n, 1n], [0n, 1n, 2n])", () => M.test2([13n, 5n, 2n, 1n], [0n, 1n, 2n]), "#[13, 5, 2, 1, 0, 1, 2]", false);
check("test2([13n, 5n, 2n, 1n], [13n, 5n, 2n, 1n])", () => M.test2([13n, 5n, 2n, 1n], [13n, 5n, 2n, 1n]), "#[13, 5, 2, 1, 13, 5, 2, 1]", false);
check("test4([])", () => M.test4([]), "#[1, 2]", false);
check("test4([0n])", () => M.test4([0n]), "#[1, 2, 0]", false);
check("test4([0n, 1n, 2n])", () => M.test4([0n, 1n, 2n]), "#[1, 2, 0, 1, 2]", false);
check("test4([13n, 5n, 2n, 1n])", () => M.test4([13n, 5n, 2n, 1n]), "#[1, 2, 13, 5, 2, 1]", false);
check("test5(0n)", () => M.test5(0n), "#[]", false);
check("test5(1n)", () => M.test5(1n), "#[0, 0]", false);
check("test5(2n)", () => M.test5(2n), "#[0, 0, 1, 1]", false);
check("test5(5n)", () => M.test5(5n), "#[0, 0, 1, 1, 2, 4, 3, 9, 4, 16]", false);
check("test5(13n)", () => M.test5(13n), "#[0, 0, 1, 1, 2, 4, 3, 9, 4, 16, 5, 25, 6, 36, 7, 49, 8, 64, 9, 81, 10, 100, 11, 121, 12, 144]", false);

console.log(`ArrayAppend-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
